  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Determine whether this booking request is valid and can be accepted under ORS booking rules.
   * Algorithm:
   * 1. Check input validity:
   *    - this.bookingDate is not null
   *    - this.customer is not null
   *    - this.trip is not null
   *    - this.numberOfSeats > 0
   * 2. Verify the trip has enough remaining seats:
   *    - remainingSeats = trip.numberOfSeats - trip.getBookedSeats()
   *    - if requested seats > remainingSeats, return false
   * 3. Check booking time constraint:
   *    - bookingDate must be strictly earlier than trip departure time by more than 2 hours
   *    - if booking is exactly 2 hours before departure, return false
   * 4. Check customer overlap constraint:
   *    - for each existing booking in customer.bookings
   *      - if existing booking is on the same day and overlapsWith(this.trip) is true, return false
   * 5. If all checks pass, return true.
   * Related Features:
   * - bookingDate
   * - numberOfSeats
   * - customer
   * - trip
   * - customer.bookings
   * - trip.numberOfSeats
   * - trip.departureTime
   * - trip.getBookedSeats()
   * - overlapsWith(trip: Trip)
   * Related Classes: Booking, Customer, Trip
   * Input:
   * - bookingDate: EDate stored in this.bookingDate; must represent the booking creation date/time.
   * - numberOfSeats: requested seat count; must be a positive integer.
   * - customer: related customer; must not be null.
   * - trip: related trip; must not be null.
   * Output:
   * - boolean:
   *   - true if the booking is eligible and can be accepted
   *   - false otherwise
   * Pre-condition:
   * - The Booking instance exists.
   * - bookingDate, customer, and trip are available for evaluation.
   * - If any of bookingDate, customer, or trip is null, the result must be false.
   * Post-condition:
   * - No state changes are required by validation itself.
   * - If the result is true and the booking is later accepted, the trip seat inventory shall be reduced by updateTripSeats() or trip.bookSeats().
   * <!-- end-model-doc -->
   * @model kind="operation"
   *        annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean isBookingEligible()
  {
    if (bookingDate == null || customer == null || trip == null || numberOfSeats <= 0)
    {
      return false;
    }

    int remainingSeats = trip.getNumberOfSeats() - trip.getBookedSeats();
    if (numberOfSeats > remainingSeats)
    {
      return false;
    }

    if (trip.getDepartureTime() == null)
    {
      return false;
    }

    long bookingTime = bookingDate.getTime();
    long departureTime = Long.parseLong(trip.getDepartureTime());
    long twoHoursMillis = 2L * 60L * 60L * 1000L;
    long diff = departureTime - bookingTime;
    if (diff <= twoHoursMillis)
    {
      return false;
    }

    if (customer.getBookings() != null)
    {
      for (Booking existingBooking : customer.getBookings())
      {
        if (existingBooking != null && existingBooking != this && existingBooking.getBookingDate() != null
            && existingBooking.getTrip() != null && existingBooking.getBookingDate().equals(bookingDate)
            && existingBooking.overlapsWith(trip))
        {
          return false;
        }
      }
    }

    return true;
  }

