    long bookingDay = bookingDate.getTime() / (24L * 60L * 60L * 1000L);
    long thisDepartureDay = Long.parseLong(this.trip.getDepartureTime()) / (24L * 60L * 60L * 1000L);
    long otherDepartureDay = Long.parseLong(trip.getDepartureTime()) / (24L * 60L * 60L * 1000L);
    if (bookingDay != thisDepartureDay || bookingDay != otherDepartureDay)
    {
      return false;
    }

    long thisDeparture = Long.parseLong(this.trip.getDepartureTime());
    long thisArrival = Long.parseLong(this.trip.getArrivalTime());
    long otherDeparture = Long.parseLong(trip.getDepartureTime());
